async function*asyncRange(n,a){for(let t=n;t<=a;t++)await Promise.resolve(),yield t*t}async function main(){const n=[];for await(const a of asyncRange(1,5))n.push(a);print("squares via for-await-of:",n.join(","));const a=asyncRange(10,12);let t=await a.next();for(;!t.done;)print("manual next:",t.value),t=await a.next()}main().then(function(){print("done")});